        self.pattern_memory = PatternMemory()
        self.learning_agent = LearningAgent(self.pattern_memory)

        # 대시보드 클라이언트 초기화
        self.dashboard_client = DashboardClient(self.state.session_id)

        # 결과
        self._result = None

